export const PERKS={health:{name:'Paid Sick Leave',desc:'+10 starting health per rank',icon:'❤️'},damage:{name:'Hazard Pay',desc:'+6% weapon damage per rank',icon:'💥'},pickup:{name:'Deep Pockets',desc:'+20 Petty Cash collection range per rank',icon:'🧲'}};
// version 4 (Build 19) adds bestSurvival: the longest survival run, in seconds.
export function fresh(){return {version:4,clearedStages:[],credits:0,runs:0,wins:0,kills:0,bestSurvival:0,perks:{health:0,damage:0,pickup:0},start:'plunger'};}
export function normalize(p){let n=fresh();for(let k of ['credits','runs','wins','kills'])n[k]=Number.isFinite(p?.[k])?Math.max(0,Math.floor(p[k])):0;if(p&&p.version!==2&&p.version!==3&&p.version!==4)n.credits*=10;n.bestSurvival=Number.isFinite(p?.bestSurvival)?Math.max(0,Math.round(p.bestSurvival*10)/10):0;n.clearedStages=Array.isArray(p?.clearedStages)?[...new Set(p.clearedStages.filter(id=>id===1||id===2))]:n.wins>0?[1]:[];if(n.clearedStages.includes(2)&&!n.clearedStages.includes(1))n.clearedStages.unshift(1);for(let k in n.perks)n.perks[k]=Math.max(0,Math.min(3,Math.floor(Number(p?.perks?.[k])||0)));if(p?.start==='tp'&&n.kills>=200)n.start='tp';if(p?.start==='gas'&&n.wins>=1)n.start='gas';return n;}
export function cost(rank){return 250+rank*300;}
export function buy(p,key){if(!(key in PERKS)||p.perks[key]>=3||p.credits<cost(p.perks[key]))return false;p.credits-=cost(p.perks[key]);p.perks[key]++;return true;}
export function settle(p,g){if(g.rewardClaimed||!['won','lost'].includes(g.state))return 0;g.rewardClaimed=true;let amount=Math.max(0,Math.floor(g.tokens||0));p.credits+=amount;p.runs++;p.kills+=g.kills;if(g.stage?.endless){g.previousBest=p.bestSurvival||0;g.newBest=g.t>g.previousBest;if(g.newBest)p.bestSurvival=Math.round(g.t*10)/10;}if(g.state==='won'){p.wins++;let id=g.stage?.id||1;if(!p.clearedStages.includes(id))p.clearedStages.push(id);}return amount;}
